function burst(x,y,color,n=8){for(let i=0;i<n;i++)particles.push({x,y,vx:(Math.random()-.5)*190,vy:-Math.random()*180-30,life:.45+Math.random()*.35,color});}
function update(dt){
  elapsed+=dt;if(invincible>0)invincible-=dt;
  const accel=1500,maxSpeed=245;
  if(keys.left){player.vx-=accel*dt;player.facing=-1;}if(keys.right){player.vx+=accel*dt;player.facing=1;}
  if(!keys.left&&!keys.right)player.vx*=Math.pow(.001,dt);player.vx=Math.max(-maxSpeed,Math.min(maxSpeed,player.vx));
  if(keys.jump&&!wasJump&&player.grounded){player.vy=-545;player.grounded=false;beep(420,.09,'square',.025);}wasJump=keys.jump;
  player.x+=player.vx*dt;player.x=Math.max(0,Math.min(worldWidth-player.w,player.x));
  const oldBottom=player.y+player.h;player.vy+=1450*dt;player.y+=player.vy*dt;player.grounded=false;
  const feet=player.y+player.h,center=player.x+player.w/2;
  if(player.vy>=0&&oldBottom<=GROUND+2&&feet>=GROUND&&!isPit(center)){player.y=GROUND-player.h;player.vy=0;player.grounded=true;}
  for(const p of platforms){if(player.x+player.w>p.x&&player.x<p.x+p.w){if(player.vy>=0&&oldBottom<=p.y+4&&feet>=p.y){player.y=p.y-player.h;player.vy=0;player.grounded=true;}else if(player.vy<0&&player.y<p.y+14&&player.y>p.y-25){player.y=p.y+13;player.vy=20;}}}
  player.walk+=Math.abs(player.vx)*dt*.075;
  for(const c of coins){if(c.taken)continue;const dx=center-c.x,dy=player.y+player.h*.48-c.y;if(dx*dx+dy*dy<30*30){c.taken=true;coinCount++;score+=100;syncHud();beep(900+Math.min(coinCount,8)*45,.07,'square',.025);burst(c.x,c.y,'#ffe773',5);if(coinCount%10===0){lives=Math.min(5,lives+1);syncHud();showToast('EXTRA HEART!');}}}
  for(const e of enemies){if(!e.alive)continue;e.x+=e.vx*dt;if(e.x<e.min||e.x>e.max)e.vx*=-1;
    if(player.x<e.x+e.w&&player.x+player.w>e.x&&player.y<e.y+e.h&&player.y+player.h>e.y){if(player.vy>80&&oldBottom<e.y+12){e.alive=false;player.vy=-340;score+=250;syncHud();burst(e.x+e.w/2,e.y,'#9b6445',12);beep(220,.11,'square');showToast('NICE STOMP!');}else if(invincible<=0){lives--;syncHud();invincible=1.5;player.vy=-300;player.vx=player.x<e.x?-230:230;beep(160,.22,'sawtooth');showToast(lives?'OOPS!':'');if(lives<=0){finish(false);return;}}}}
  if(player.y>H+75){lives--;syncHud();if(lives<=0){finish(false);return;}player.x=Math.max(0,player.x-220);player.y=GROUND-player.h;player.vy=0;invincible=1.7;showToast('BACK IN THE GAME!');}
  for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=360*dt;p.life-=dt;}particles=particles.filter(p=>p.life>0);
  camera=Math.max(0,Math.min(worldWidth-W,player.x-W*.36));
  if(player.x>worldWidth-125){score+=coinCount*25;syncHud();finish(true);}
}
function rect(x,y,w,h,color){ctx.fillStyle=color;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h));}
function drawCloud(x,y,s=1){ctx.fillStyle='#fff9e8';ctx.fillRect(x,y+12*s,66*s,21*s);ctx.fillRect(x+12*s,y,25*s,24*s);ctx.fillRect(x+34*s,y+4*s,24*s,22*s);ctx.fillStyle='#d9f6fc';ctx.fillRect(x,y+28*s,66*s,5*s);}
function drawBackground(){
  const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#69d2f3');sky.addColorStop(.72,'#b3edee');sky.addColorStop(1,'#e4f6d5');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
  ctx.fillStyle='#fff1a7';ctx.beginPath();ctx.arc(790,115,43,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff8ce';ctx.beginPath();ctx.arc(790,115,34,0,Math.PI*2);ctx.fill();
  for(let i=0;i<7;i++){const x=((i*205-camera*.2)%1200+1200)%1200-100;drawCloud(x,73+(i%3)*49,.75+(i%2)*.22);}
  for(let i=0;i<7;i++){const x=((i*240-camera*.34)%1450+1450)%1450-180;ctx.fillStyle=i%2?'#8edba8':'#78d2a0';ctx.beginPath();ctx.ellipse(x+105,420,155,130,0,Math.PI,0);ctx.fill();ctx.fillStyle='#c1eaa6';ctx.beginPath();ctx.ellipse(x+100,432,87,67,0,Math.PI,0);ctx.fill();}
  for(let i=0;i<8;i++){const x=((i*177-camera*.55)%1500+1500)%1500-120;ctx.fillStyle=i%2?'#58c788':'#48b981';ctx.beginPath();ctx.ellipse(x+65,445,100,65,0,Math.PI,0);ctx.fill();}
}
function drawGround(){
  // Grass and warm soil are built from chunky pixel bands.
  rect(camera,GROUND,worldWidth,18,'#66cf69');rect(camera,GROUND+18,worldWidth,H-GROUND,'#b86c4d');rect(camera,GROUND+18,worldWidth,9,'#a85d43');
  for(let x=Math.floor(camera/32)*32;x<camera+W;x+=32){if(isPit(x+16))continue;rect(x,GROUND+18,16,5,'#c78159');rect(x+19,GROUND+36,9,5,'#99523f');rect(x+5,GROUND+56,13,4,'#c17a56');rect(x+4,GROUND-5,8,5,'#9ee078');}
  for(const pit of pits){rect(pit.x,GROUND,pit.w,H-GROUND+10,'#344e5b');rect(pit.x+5,GROUND+5,pit.w-10,H-GROUND,'#24394a');rect(pit.x,GROUND,pit.w,6,'#dd9b62');}
}
function drawCoin(c){const bob=Math.sin(elapsed*6+c.x*.04)*3;ctx.fillStyle='#f6aa34';ctx.fillRect(c.x-8,c.y-12+bob,16,24);ctx.fillStyle='#ffdf62';ctx.fillRect(c.x-5,c.y-11+bob,10,20);ctx.fillStyle='#fff2a1';ctx.fillRect(c.x-2,c.y-8+bob,3,7);}
function drawPlatform(p){rect(p.x,p.y,p.w,17,'#b96548');rect(p.x,p.y,p.w,8,'#69d269');rect(p.x+4,p.y+9,p.w-8,4,'#d38256');for(let x=p.x+12;x<p.x+p.w;x+=26){rect(x,p.y+17,4,9,'#99523f');}}
function drawEnemy(e){if(!e.alive)return;const x=e.x,y=e.y;rect(x+5,y+5,20,19,'#9a583a');rect(x+3,y+10,24,12,'#b56b43');rect(x+8,y+7,4,6,'#fff');rect(x+18,y+7,4,6,'#fff');rect(x+9,y+8,2,4,'#233047');rect(x+19,y+8,2,4,'#233047');rect(x,y+22,11,6,'#603c3a');rect(x+19,y+22,11,6,'#603c3a');rect(x+4,y+2,22,5,'#d4895b');}
function drawPlayer(){if(invincible>0&&Math.floor(elapsed*14)%2===0)return;const x=player.x,y=player.y,step=Math.floor(player.walk)%2;ctx.save();if(player.facing<0){ctx.translate(x*2+player.w,0);ctx.scale(-1,1);}else ctx.translate(x,0);
  // Berry-red cap and scarf, cream tunic, tiny boots: all original pixel-art shapes.
