  rect(8,y+13,17,4,'#f1bd86');rect(7,y+17,19,14,'#287d91');rect(4,y+20,5,11,'#e85755');rect(25,y+20,5,11,'#e85755');
  rect(10,y+19,4,4,'#fff1c6');rect(20,y+19,4,4,'#fff1c6');rect(14,y+23,4,3,'#f2c956');rect(6,y+31,10,5,'#f4d18c');rect(17,y+31,10,5,'#f4d18c');
  rect(step?4:6,y+36,11,8,'#51435a');rect(step?18:17,y+36,11,8,'#51435a');rect(step?2:4,y+41,13,3,'#34334b');rect(step?18:16,y+41,14,3,'#34334b');ctx.restore();
}

